<script setup lang="ts">
import { serviceJobTotal } from "~/utils/service-items"
import { serviceLabel, serviceStatusColor, serviceDate, serviceCurrency, serviceMatches } from '~/utils/after-sales-display'
import { serviceToday } from '~/utils/after-sales'
import { billingErrorMessage } from '~/utils/billing-error'
const scope=useCompanyScope('form',true);await scope.ready
const route=useRoute(),detail=ref<any>(null),error=ref(''),busy=ref(false),editing=ref<any>(null),action=ref(''),reason=ref(''),values=ref<any>({}),recordedOn=ref(serviceToday()),dates=ref<any>({}),replacementId=ref(''),restart=ref(false),readingAgreementId=ref(''),replacementOptions=ref<any[]>([])
const jobBusy=ref(false)
const invoicePrompt=ref<any>(null),invoicing=ref(false),invoiceError=ref('')
const historyTab=ref('jobs'), jobSearch=ref(''), loading=ref(false)
const fields=computed(()=>detail.value?.agreements.find((a:any)=>a.id===readingAgreementId.value)?.snapshot.rules.fields||[])
let version=0
async function load(){const token=++version;error.value='';loading.value=true;try{const result=await scope.fetch<any>('/api/after-sales/products/'+route.params.customerProductId);if(token!==version)return;detail.value=result;const p=result.product;dates.value={installedOn:p.installed_on||'',deliveredOn:p.delivered_on||'',serialNumber:p.serial_number||''};const job=result.jobs.find((j:any)=>j.id===route.query.jobId);if(job)openJob(result.agreements.find((a:any)=>a.id===job.agreement_id),job);else if(route.query.agreementId)openJob(result.agreements.find((a:any)=>a.id===route.query.agreementId))}catch(e){if(token===version)error.value=billingErrorMessage(e)}finally{if(token===version)loading.value=false}}
onMounted(load);watch(()=>[route.params.customerProductId,route.query.jobId,route.query.agreementId,route.query.occurrenceId],()=>{editing.value=null;void load()})
async function chooseReplacement(){action.value='REPLACE';try{replacementOptions.value=(await scope.fetch<any[]>('/api/after-sales/products',{query:{clientId:detail.value.product.client_id}})).filter(p=>p.id!==detail.value.product.id&&p.status==='ACTIVE')}catch(e){error.value=billingErrorMessage(e)}}
function openJob(agreement:any,job?:any){if(agreement)editing.value={agreement,job,key:crypto.randomUUID()}}
async function saved(result?:{id:string}){
  editing.value=null
  await navigateTo({path:route.path,query:{entryCompany:scope.companyId.value}},{replace:true})
  await load()
  const job=detail.value?.jobs.find((j:any)=>j.id===result?.id)
  if(!job)return
  if(!job.bill_id&&['COMPLETED','RESOLVED'].includes(job.status)){
    invoiceError.value='';invoicePrompt.value=job
  }else openJob(detail.value.agreements.find((a:any)=>a.id===job.agreement_id),job)
}
function invoiceLater(){
  if(invoicing.value)return
  const job=invoicePrompt.value
  invoicePrompt.value=null;invoiceError.value=''
  if(job)openJob(detail.value?.agreements.find((a:any)=>a.id===job.agreement_id),job)
}
async function createSavedInvoice(){
  if(invoicing.value||!invoicePrompt.value)return
  invoicing.value=true;invoiceError.value=''
  try{
    const result=await scope.fetch<any>('/api/after-sales/jobs/invoice',{method:'POST',body:{id:invoicePrompt.value.id}})
    await navigateTo({path:'/erp/edit/'+result.billId,query:{entryCompany:scope.companyId.value}})
    invoicePrompt.value=null
  }catch(e){invoiceError.value=billingErrorMessage(e)}finally{invoicing.value=false}
}
async function update(){busy.value=true;error.value='';try{await scope.fetch('/api/after-sales/products/update',{method:'POST',body:{id:detail.value.product.id,action:action.value,reason:reason.value,agreementId:readingAgreementId.value,values:values.value,recordedOn:recordedOn.value,...dates.value,replacementId:replacementId.value,restart:restart.value}});action.value='';reason.value='';await load()}catch(e){error.value=billingErrorMessage(e)}finally{busy.value=false}}
const currency=computed(()=>scope.auth.session.value?.currency||'INR')
const jobColumns=[{key:'kind',label:'Type'},{key:'agreement_name',label:'Plan / coverage'},{key:'status',label:'Status'},{key:'total',label:'Amount'},{key:'invoice',label:'Invoice'},{key:'actions',label:''}]
const filteredJobs=computed(()=>(detail.value?.jobs||[]).filter((job:any)=>serviceMatches(job,jobSearch.value)))
const actionTitle=computed(()=>action.value==='DATES'?'Edit serial and activation dates':action.value==='READING'?'Record readings':action.value==='RETURN'?'Record completed return':'Replace client product')
</script>
<template>
  <UDashboardPanelContent class="pb-24">
    <div class="mb-5"><UButton :to="{path:'/after-sales',query:{entryCompany:scope.companyId.value}}" color="gray" variant="link" icon="i-heroicons-arrow-left" class="p-0">Service workspace</UButton></div>
    <UAlert v-if="error" role="alert" color="red" variant="soft" icon="i-heroicons-exclamation-circle" :title="error" description="Refresh this client product to try again." class="mb-4"><template #actions><UButton color="red" variant="ghost" @click="load">Retry</UButton></template></UAlert>
    <div v-if="loading&&!detail" class="space-y-4"><USkeleton class="h-36 w-full"/><div class="grid grid-cols-1 gap-4 sm:grid-cols-2"><USkeleton class="h-56"/><USkeleton class="h-56"/></div></div>
    <template v-if="detail">
      <div class="mb-5 flex flex-wrap items-start justify-between gap-3"><div><div class="flex flex-wrap items-center gap-3"><h1 class="text-xl font-semibold text-gray-900 dark:text-white">{{detail.product.name}}</h1><UBadge :color="serviceStatusColor(detail.product.status)" variant="subtle">{{serviceLabel(detail.product.status)}}</UBadge></div><p class="mt-1 text-sm text-gray-500 dark:text-gray-400">{{detail.product.reference}}</p></div><div class="flex gap-2"><UButton v-if="detail.product.bill_id" :to="{path:'/erp/edit/'+detail.product.bill_id,query:{entryCompany:scope.companyId.value}}" color="gray" icon="i-heroicons-document-text">Original invoice</UButton><UDropdown :items="[[{label:'Edit serial / activation dates',icon:'i-heroicons-pencil-square',click:()=>action='DATES'},{label:'Record readings',icon:'i-heroicons-clipboard-document-check',click:()=>action='READING'}],...(detail.product.status==='ACTIVE'?[[{label:'Record completed return',icon:'i-heroicons-arrow-uturn-left',click:()=>action='RETURN'},{label:'Record replacement',icon:'i-heroicons-arrow-path',click:chooseReplacement}]]:[])]"><UButton color="gray" trailing-icon="i-heroicons-chevron-down">Actions</UButton></UDropdown></div></div>
      <UCard class="mb-6"><dl class="grid grid-cols-1 gap-5 text-sm sm:grid-cols-2 lg:grid-cols-4"><div><dt class="text-gray-500 dark:text-gray-400">Client</dt><dd class="mt-1 font-medium">{{detail.product.customer_name}}</dd><dd class="mt-1 text-xs text-gray-500 dark:text-gray-400">{{detail.product.phone}}</dd></div><div><dt class="text-gray-500 dark:text-gray-400">Serial number</dt><dd class="mt-1 font-medium">{{detail.product.serial_number||'Not recorded'}}</dd></div><div><dt class="text-gray-500 dark:text-gray-400">Purchase date</dt><dd class="mt-1 font-medium">{{serviceDate(detail.product.purchased_on)}}</dd></div><div><dt class="text-gray-500 dark:text-gray-400">Installation / delivery</dt><dd class="mt-1 font-medium">{{serviceDate(detail.product.installed_on)}} / {{serviceDate(detail.product.delivered_on)}}</dd></div></dl></UCard>
      <section class="mb-6"><div class="mb-4"><h2 class="text-base font-semibold">Coverage and maintenance</h2><p class="mt-1 text-sm text-gray-500 dark:text-gray-400">Select an agreement to create a visit or start a claim.</p></div><div class="grid grid-cols-1 gap-4 xl:grid-cols-2"><UCard v-for="a in detail.agreements" :key="a.id"><template #header><div class="flex items-start justify-between gap-3"><div><p class="text-xs font-medium uppercase tracking-wide text-gray-500 dark:text-gray-400">{{serviceLabel(a.kind)}}</p><h3 class="mt-1 font-semibold">{{a.snapshot.name}}</h3></div><UBadge :color="serviceStatusColor(a.status)" variant="subtle" size="xs">{{serviceLabel(a.status)}}</UBadge></div></template><dl class="grid grid-cols-2 gap-4 text-sm"><div><dt class="text-gray-500 dark:text-gray-400">Starts</dt><dd class="mt-1">{{a.starts_on?serviceDate(a.starts_on):'Pending activation'}}</dd></div><div><dt class="text-gray-500 dark:text-gray-400">Ends</dt><dd class="mt-1">{{a.ends_on?serviceDate(a.ends_on):'No fixed end'}}</dd></div><template v-if="a.kind==='MAINTENANCE'"><div><dt class="text-gray-500 dark:text-gray-400">Next visit</dt><dd class="mt-1" :class="a.next_due&&a.next_due<serviceToday()?'text-red-500 font-medium':''">{{serviceDate(a.next_due)}}</dd></div><div><dt class="text-gray-500 dark:text-gray-400">Completed / free visits remaining</dt><dd class="mt-1">{{a.completed_visits}} / {{Math.max(0,a.snapshot.rules.freeVisits-a.completed_visits)}}</dd></div></template></dl><p v-if="a.snapshot.rules.coverage" class="mt-4 whitespace-pre-line text-sm">{{a.snapshot.rules.coverage}}</p><details v-if="a.snapshot.rules.exclusions||a.snapshot.rules.instructions" class="mt-4 text-sm"><summary class="cursor-pointer text-gray-500 dark:text-gray-400">Terms and instructions</summary><p v-if="a.snapshot.rules.exclusions" class="mt-2 whitespace-pre-line">{{a.snapshot.rules.exclusions}}</p><p class="mt-2 whitespace-pre-line text-gray-500 dark:text-gray-400">{{a.snapshot.rules.instructions}}</p></details><template #footer><UButton v-if="detail.product.status==='ACTIVE'&&['ACTIVE','PENDING','EXPIRED'].includes(a.status)" color="gray" icon="i-heroicons-plus" @click="openJob(a)">{{a.kind==='MAINTENANCE'?'Add service visit':'Open claim'}}</UButton><p v-else class="text-xs text-gray-500 dark:text-gray-400">This agreement is retained for service history.</p></template></UCard></div><UAlert v-if="!detail.agreements.length" color="gray" variant="soft" icon="i-heroicons-shield-check" title="No agreements on this product"/></section>
      <div class="mb-4 flex flex-wrap gap-1" role="group" aria-label="Product history"><UButton v-for="item in [{key:'jobs',label:'Claims and service history'},{key:'readings',label:'Recorded readings'},{key:'changes',label:'Change history'}]" :key="item.key" :color="historyTab===item.key?'primary':'gray'" :variant="historyTab===item.key?'soft':'ghost'" :aria-pressed="historyTab===item.key" @click="historyTab=item.key">{{item.label}}</UButton></div>
      <AfterSalesRecordTable v-if="historyTab==='jobs'" v-model:search="jobSearch" :rows="filteredJobs" :columns="jobColumns" :loading="loading" search-placeholder="Search service history" empty-label="No service history yet" empty-description="Create a visit or claim from an agreement above." @refresh="load"><template #kind-data="{row}">{{serviceLabel(row.kind)}}</template><template #status-data="{row}"><UBadge :color="serviceStatusColor(row.status)" variant="subtle">{{serviceLabel(row.status)}}</UBadge></template><template #total-data="{row}">{{serviceCurrency(serviceJobTotal(row),currency)}}</template><template #invoice-data="{row}"><UButton v-if="row.bill_id" :to="{path:'/erp/edit/'+row.bill_id,query:{entryCompany:scope.companyId.value}}" color="primary" variant="link" class="p-0">{{row.invoice_code||'View invoice'}}</UButton><span v-else class="text-xs text-gray-500 dark:text-gray-400">Not invoiced</span><p v-if="row.bill_id" class="mt-1 text-xs text-gray-500 dark:text-gray-400">{{row.bill_deleted?'Invoice deleted':serviceLabel(row.payment_status)}}</p></template><template #actions-data="{row}"><UButton color="gray" variant="ghost" trailing-icon="i-heroicons-arrow-right" @click="openJob(detail.agreements.find((a:any)=>a.id===row.agreement_id),row)">View job</UButton></template></AfterSalesRecordTable>
      <div v-else-if="historyTab==='readings'" class="space-y-4"><UCard v-for="reading in detail.readings" :key="reading.id"><template #header><div class="flex items-center gap-2"><UIcon name="i-heroicons-clipboard-document-check" class="h-5 w-5 text-gray-400"/><h3 class="text-sm font-semibold">{{serviceDate(reading.recorded_on)}}</h3></div></template><dl class="grid grid-cols-1 gap-4 text-sm sm:grid-cols-2"><div v-for="(value,key) in (reading.values.fields||reading.values)" :key="key"><dt class="text-gray-500 dark:text-gray-400">{{(reading.values.definitions||detail.agreements.find((a:any)=>a.id===reading.values.agreementId)?.snapshot.rules.fields||[]).find((f:any)=>f.key===key)?.label||key}}</dt><dd class="mt-1 font-medium">{{typeof value==='boolean'?(value?'Yes':'No'):value}}</dd></div></dl></UCard><UAlert v-if="!detail.readings.length" color="gray" variant="soft" icon="i-heroicons-clipboard" title="No readings recorded" description="Use Actions > Record readings to add a manual reading."/></div>
      <UCard v-else><div class="divide-y divide-gray-100 dark:divide-gray-800"><div v-for="entry in detail.history" :key="entry.id" class="py-4 first:pt-0 last:pb-0"><div class="flex flex-wrap items-center justify-between gap-2"><h3 class="text-sm font-medium">{{serviceLabel(entry.action)}}</h3><span class="text-xs text-gray-500 dark:text-gray-400">{{serviceDate(entry.created_at)}}</span></div><p class="mt-2 text-sm text-gray-500 dark:text-gray-400">{{entry.reason}}</p><details class="mt-2 text-xs"><summary class="cursor-pointer text-gray-500 dark:text-gray-400">View recorded details</summary><div class="mt-2 grid gap-3 md:grid-cols-2"><pre class="overflow-auto rounded-md bg-gray-50 p-3 dark:bg-gray-800">{{entry.before}}</pre><pre class="overflow-auto rounded-md bg-gray-50 p-3 dark:bg-gray-800">{{entry.after}}</pre></div></details></div><p v-if="!detail.history.length" class="py-6 text-center text-sm text-gray-500 dark:text-gray-400">No changes recorded.</p></div></UCard>
    </template>
    <USlideover :model-value="!!editing" :prevent-close="jobBusy" :ui="{width:'sm:max-w-3xl'}" @update:model-value="value=>{if(!value&&!jobBusy)editing=null}"><AfterSalesJobEditor v-if="editing" :key="editing.key" :agreement="editing.agreement" :job="editing.job" :occurrence-id="String(route.query.occurrenceId||'')||undefined" @saved="saved" @cancel="editing=null" @busy="jobBusy=$event"/></USlideover>
    <UModal :model-value="!!invoicePrompt" :prevent-close="invoicing" :ui="{width:'sm:max-w-md'}" @update:model-value="value=>{if(!value)invoiceLater()}">
      <UCard v-if="invoicePrompt">
        <template #header><div class="flex items-center gap-3"><UIcon name="i-heroicons-document-plus" class="h-6 w-6 text-primary"/><h2 class="text-lg font-semibold">Create service invoice?</h2></div></template>
        <p class="text-sm text-gray-500 dark:text-gray-400">{{invoicePrompt.status==='RESOLVED'?'The claim was resolved and saved.':'The service visit was completed and saved.'}} Would you like to create its invoice now?</p>
        <div class="mt-5 flex items-center justify-between gap-3 rounded-lg bg-gray-50 p-4 dark:bg-gray-800"><span class="text-sm text-gray-500 dark:text-gray-400">Invoice total</span><strong class="text-lg tabular-nums">{{serviceCurrency(serviceJobTotal(invoicePrompt),currency)}}</strong></div>
        <UAlert v-if="invoiceError" role="alert" color="red" variant="soft" :title="invoiceError" class="mt-4"/>
        <template #footer><div class="flex justify-end gap-2"><UButton type="button" color="white" :disabled="invoicing" @click="invoiceLater">Later</UButton><UButton type="button" icon="i-heroicons-document-plus" :loading="invoicing" :disabled="invoicing" @click="createSavedInvoice">Create invoice</UButton></div></template>
      </UCard>
    </UModal>
    <UModal :model-value="!!action" :prevent-close="busy" :ui="{width:'sm:max-w-xl'}" @update:model-value="value=>{if(!value&&!busy)action=''}"><UCard v-if="action&&detail"><template #header><div class="flex items-center justify-between"><h2 class="font-semibold">{{actionTitle}}</h2><UButton color="gray" variant="ghost" icon="i-heroicons-x-mark" aria-label="Close product action" :disabled="busy" @click="action=''"/></div></template><form id="customer-product-action" class="space-y-4" @submit.prevent="update"><fieldset :disabled="busy" class="space-y-4"><div v-if="action==='DATES'" class="grid grid-cols-1 gap-4 sm:grid-cols-2"><UFormGroup label="Serial number" class="sm:col-span-2"><UInput v-model="dates.serialNumber"/></UFormGroup><UFormGroup label="Delivery date"><UInput v-model="dates.deliveredOn" type="date"/></UFormGroup><UFormGroup label="Installation date"><UInput v-model="dates.installedOn" type="date"/></UFormGroup></div><template v-if="action==='READING'"><UFormGroup label="Recorded on" required><UInput v-model="recordedOn" type="date" required/></UFormGroup><UFormGroup label="Agreement" required><USelect v-model="readingAgreementId" :options="[{value:'',label:'Select an agreement'},...detail.agreements.map((a:any)=>({value:a.id,label:serviceLabel(a.kind)+' - '+a.snapshot.name}))]" required @update:model-value="values={}"/></UFormGroup><AfterSalesValuesEditor v-model="values" :fields="fields"/></template><UAlert v-if="action==='RETURN'" color="orange" variant="soft" icon="i-heroicons-exclamation-triangle" title="Confirm the physical return is complete" description="This ends remaining coverage and maintenance. Stock and refunds use the normal return workflow."/><template v-if="action==='REPLACE'"><UFormGroup label="Replacement product" required help="Register the replacement first if it is not listed."><USelect v-model="replacementId" :options="[{value:'',label:'Select a registered replacement'},...replacementOptions.map(p=>({value:p.id,label:p.name+' - '+p.reference}))]" required/></UFormGroup><UCheckbox v-model="restart" label="Restart coverage" help="Otherwise the original coverage and remaining maintenance continue on the replacement."/></template><UFormGroup label="Reason" required><UTextarea v-model="reason" required maxlength="2000" placeholder="Explain this change for the service history"/></UFormGroup></fieldset><UAlert v-if="error" role="alert" color="red" variant="soft" :title="error"/></form><template #footer><div class="flex justify-end gap-2"><UButton color="white" :disabled="busy" @click="action=''">Cancel</UButton><UButton type="submit" form="customer-product-action" :color="action==='RETURN'?'red':'primary'" :loading="busy" :disabled="!reason.trim()">Confirm change</UButton></div></template></UCard></UModal>
  </UDashboardPanelContent>
</template>
